"""Doré Design P1 — hover/tap motion lab for Living Water 8:5 currents."""

PAGE_ID='motion-p1-living-current'

def _page():
    return {
        'id':PAGE_ID,'name':'Motion · P1 Hover Assembly','canvas':{'w':1440,'h':960},'nodes':[],
        'design_experiment':{
            'schema':'dore.design-experiment.v1','track':'motion-language','prototype':'P1','status':'prototype','source':'user-direction-2026-09-09',
            'principles':['hover-is-primary-on-desktop','tap-is-fallback-on-touch','D-codrops-original-reference','E-half-screen-assembly-half-screen-mosaic','grid-never-visible-at-rest','every-selection-replays-full-assembly','piece-count-follows-visible-layout-half','multiple-independent-dore-images','layout-half-keeps-moving','assembled-half-becomes-reading-current','preview-content-flows-after-assembly','hover-stage-pauses-for-reading','no-click-required-to-read'],
            'acceptance':['one-half-remains-multi-image-layout','other-half-is-assembly-stage','desktop-hover-needs-no-click','every-new-hover-replays-full-assembly','piece-count-is-variable','pieces-use-different-visible-dore-images','source-to-target-motion-visible-every-time','layout-half-keeps-moving','assembled-preview-starts-flowing','reader-can-hover-preview-and-read-without-click','preview-resumes-flow-after-pointer-leaves','touch-tap-fallback','reversible']
        }
    }

def install_workspace(base):
    original=base.workspace
    def workspace():
        w=original()
        for p in w.get('pages',[]):
            if p.get('id')==PAGE_ID:p.update(_page());return base.save(w)
        w['pages'].append(_page());return base.save(w)
    base.workspace=workspace

def install_editor(html):
    html=html.replace("'multiwrite-cover'])","'multiwrite-cover','motion-p1-living-current'])")
    return html.replace('DORÉ DESIGN 1.9 · PROMOTION PIPELINE','DORÉ DESIGN 2.0 · DESIGN LAB')

def _card(kind,title,dore,weight,preview):
    safe=preview.replace('&','&amp;').replace('"','&quot;').replace('<','&lt;').replace('>','&gt;')
    return '<button class="flow-card w%s" data-kind="%s" data-title="%s" data-dore="%s" data-preview="%s"><span>%s</span><strong>%s</strong></button>'%(weight,kind,title,dore,safe,kind,title)

def _streams():
    rows=[
      [('SCRIPTURE','起初，光進入黑暗。',21,2,'起初，光進入黑暗。不是一個靜止的畫面，而是一條從黑暗中展開的道路。光照進來，內容便開始被看見。'),('JOURNAL','守望',39,1,'守望不是停住不動，而是在流動中辨認方向。當內容經過眼前，你可以停留、閱讀，也可以讓它繼續往前。'),('PRAYER','儆醒',46,1,'儆醒，是讓目光保持清醒。不是把畫面凍結，而是在不斷變化之中仍然認出真正重要的事情。'),('FEATURE','一座光明的城',75,2,'一座光明的城並不只是遠方的目的地。它在每一次被照亮的內容裡逐漸出現，在觀看與閱讀之間形成路徑。'),('ONE','查經',93,1,'經文、背景、串珠與歷史不是分離的卡片；它們可以彼此流入，讓閱讀從一個入口自然進入下一層。')],
      [('DAYLIGHT CAFE','共享',115,2,'共享讓不同人的看見彼此經過。內容不必等到點擊後才開始，它在靠近時就已經展開。'),('STUDY','同行',122,1,'同行意味著閱讀不是孤立事件。鼠標停留的片刻，就可以成為開始閱讀、理解與繼續前行的地方。'),('DAWN LIBRARY','黎明書局',127,3,'黎明書局不是一排靜止封面，而是一條可以經過、停留、翻閱的內容河流。書、文章與影像在同一個視覺場中交換位置。'),('STORY','看見',164,1,'看見不是一次點擊，而是一個持續發生的過程。當畫面拼合完成，故事就應當立即開始，而不是再要求一道入口。')],
      [('VIDEO','影像',170,1,'影像可以流過畫面，文字也可以。兩者不需要爭奪主導權，而是在同一個節奏裡交替浮現。'),('JOURNAL','見證人',186,2,'見證不是靜態陳列。人物、片段、文字與圖像可以在半屏之中持續移動，讓觀看逐步變成閱讀。'),('DIALOGUE','對話',192,1,'對話本身就是流動。沒有必要先進入另一頁才開始理解，預覽層已經可以承載真正的閱讀。'),('PRAYER','你們要禱告',198,2,'禱告的內容可以在畫面中緩慢經過。當使用者把鼠標停在其中，它便安靜下來，讓人真正讀完。')],
      [('HYMN','頌讚',216,1,'頌讚有自己的節奏，並不需要用按鈕開始。它可以像水一樣經過，停留時被聽見，被讀見。'),('MARANATHA','主啊，我願你來。',224,3,'等待並不是空白。內容在等待中仍然前行，一段接一段地經過，直到使用者願意停留在其中。'),('CHURCH','Living Water',237,1,'Living Water 的重點不是製造一次漂亮的動效，而是讓整個閱讀路徑始終有流動感。'),('SCRIPTURE','等候黎明',75,2,'等候黎明，也是在黑暗中保持方向。畫面拼合後，閱讀自然開始；當目光離開，它又繼續流動。')]
    ]
    return ''.join('<div class="current c%s">%s</div>'%(i+1,''.join(_card(*x) for x in row)) for i,row in enumerate(rows))

def render_p1(edit=False):
    badge='<div class="badge">DORÉ DESIGN · MOTION LAB · P1</div>' if edit else ''
    streams=_streams()
    return '''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>P1 Half Screen Assembly</title><style>
*{box-sizing:border-box}html,body{margin:0;background:#181713;color:#eee8d9;font-family:"Cormorant Garamond","Noto Serif TC",serif}.badge{position:fixed;z-index:99;top:10px;left:10px;background:#171714;border:1px solid #6f6748;padding:7px 9px;font:9px ui-monospace,monospace}.intro{padding:48px 5vw 24px;border-bottom:1px solid #494431}.ey,.id{font:10px ui-monospace,monospace;letter-spacing:.15em;color:#cebd74}.intro h1{font-size:clamp(38px,5vw,72px);font-weight:400;margin:.15em 0}.intro p{max-width:940px;color:#bcb4a3;line-height:1.5}.lab{display:grid;gap:30px;padding:30px 3vw 70px}.exp{border:1px solid #4a4533;background:#201f1a;overflow:hidden}.head{display:flex;gap:16px;align-items:baseline;padding:12px 14px;border-bottom:1px solid #403b2d}.head h2{font-size:22px;font-weight:400;margin:0}.note{margin-left:auto;color:#8e8778;font:10px ui-monospace,monospace}.codrops-stage{height:min(74vh,720px);min-height:600px;background:#eee}.codrops-stage iframe{width:100%;height:100%;border:0}.sourcebar,.fusion-note{padding:10px 14px;color:#a49b88;font:10px ui-monospace,monospace}.fusion{height:720px;position:relative;overflow:hidden;background:#11110e;display:grid;grid-template-columns:1fr 1fr}.layout-half{position:relative;overflow:hidden;border-right:1px solid rgba(206,189,116,.20)}.assembly-half{position:relative;overflow:hidden;background:#0d0d0b}.current{position:absolute;left:-14vw;display:flex;gap:10px;width:max-content;will-change:transform}.c1{top:3%;animation:drift1 42s linear infinite}.c2{top:27%;animation:drift2 55s linear infinite}.c3{top:51%;animation:drift3 47s linear infinite}.c4{top:75%;animation:drift4 62s linear infinite}.flow-card{height:145px;width:232px;flex:0 0 auto;border:1px solid rgba(206,189,116,.36);background:#24221b center/cover no-repeat;color:#eee8d9;text-align:left;padding:13px;cursor:pointer;position:relative;overflow:hidden;transition:border-color .16s,transform .16s,opacity .16s}.flow-card.w2{width:476px}.flow-card.w3{width:720px}.flow-card:before{content:"";position:absolute;inset:0;background:linear-gradient(0deg,rgba(9,9,7,.90),rgba(9,9,7,.05) 68%)}.flow-card span,.flow-card strong{position:relative;z-index:1;display:block}.flow-card span{font:8px ui-monospace,monospace;color:#cebd74;letter-spacing:.12em}.flow-card strong{font-size:22px;font-weight:400;margin-top:8px;max-width:18ch}.flow-card.w2 strong{font-size:29px}.flow-card.w3 strong{font-size:34px}.flow-card.selected{border-color:#cebd74;transform:translateY(-4px)}.assembly-piece{position:absolute;background:center/cover no-repeat;border:1px solid rgba(238,232,217,.18);box-shadow:0 12px 34px rgba(0,0,0,.22);opacity:0;will-change:transform,opacity}.reading-mask{position:absolute;z-index:9;inset:0;pointer-events:none;background:linear-gradient(90deg,transparent 0,rgba(8,8,6,.08) 25%,rgba(8,8,6,.52) 58%,rgba(8,8,6,.88) 100%);opacity:0;transition:opacity .35s}.assembly-half.ready .reading-mask{opacity:1}.preview-viewport{position:absolute;z-index:10;left:54%;right:5%;top:8%;bottom:8%;overflow:hidden;opacity:0;transition:opacity .35s .22s;pointer-events:none}.assembly-half.ready .preview-viewport{opacity:1;pointer-events:auto}.preview-flow{display:flex;flex-direction:column;gap:26px;padding-top:72%;animation:readingFlow 18s linear infinite;will-change:transform}.preview-card{padding:18px 0 24px;border-top:1px solid rgba(206,189,116,.42);text-shadow:0 2px 18px #000}.preview-card small{font:9px ui-monospace,monospace;letter-spacing:.15em;color:#cebd74}.preview-card h3{font-size:clamp(30px,3.4vw,54px);font-weight:400;line-height:.96;margin:.12em 0 .28em}.preview-card p{font-size:17px;line-height:1.55;color:#eee8d9;margin:0;max-width:34ch}.preview-hint{position:absolute;z-index:11;right:5%;bottom:3.5%;font:9px ui-monospace,monospace;color:#a89f8c;opacity:0;transition:opacity .35s}.assembly-half.ready .preview-hint{opacity:1}.assembly-half:hover .preview-flow{animation-play-state:paused}.assembly-half:hover .preview-hint:after{content:' · 已停留，可閱讀'}.actions{position:absolute;z-index:12;right:16px;top:16px}.actions button{border:1px solid #827752;background:#171611;color:#eee8d9;padding:8px 11px;cursor:pointer}@keyframes readingFlow{from{transform:translateY(0)}to{transform:translateY(-58%)}}@keyframes drift1{from{transform:translateX(0)}to{transform:translateX(-12vw)}}@keyframes drift2{from{transform:translateX(-9vw)}to{transform:translateX(4vw)}}@keyframes drift3{from{transform:translateX(2vw)}to{transform:translateX(-10vw)}}@keyframes drift4{from{transform:translateX(-6vw)}to{transform:translateX(6vw)}}@media(max-width:760px){.fusion{height:680px;grid-template-columns:1fr}.layout-half{height:50%;border-right:0;border-bottom:1px solid rgba(206,189,116,.20)}.assembly-half{height:50%}.flow-card{height:92px;width:148px}.flow-card.w2{width:306px}.flow-card.w3{width:464px}.current{gap:7px}.c1{top:2%}.c2{top:27%}.c3{top:52%}.c4{top:77%}.note{display:none}.preview-viewport{left:47%;top:5%;bottom:5%}.preview-card h3{font-size:30px}.preview-card p{font-size:14px}}@media(prefers-reduced-motion:reduce){.current,.preview-flow{animation:none!important}}
</style></head><body>'''+badge+'''<header class="intro"><div class="ey">MOTION LAB · P1 · HALF LAYOUT / HALF ASSEMBLY / READING CURRENT</div><h1>Living Water × Dynamic Assembly</h1><p>D 保留 Codrops 原作。E 現在不只把多張圖拼到右半屏：每一次拼合完成後，該內容的預覽立即在拼合畫面內繼續流動。鼠標移到右半屏即可停住文字開始閱讀，不需要再點一次進入下一層。</p></header><main class="lab"><section class="exp"><div class="head"><span class="id">D</span><h2>Codrops · Original Reference</h2><span class="note">Gwen Bogaert · GSAP + clip-path</span></div><div class="codrops-stage"><iframe src="https://tympanus.net/Tutorials/GridToFullPreview/" title="Codrops Grid To Full Preview"></iframe></div><div class="sourcebar">成熟原作保留，用作動態基準。</div></section><section class="exp"><div class="head"><span class="id">E</span><h2>Living Water × Half-Screen Assembly + Reading Current</h2><span class="note">assemble → preview keeps flowing → hover to read</span></div><div class="fusion" id="fusion"><div class="layout-half" id="layoutHalf">'''+streams+'''</div><div class="assembly-half" id="assemblyHalf"><div class="reading-mask"></div><div class="preview-viewport"><div class="preview-flow" id="previewFlow"></div></div><div class="preview-hint">內容正在流動</div><div class="actions"><button id="clear">清除</button></div></div></div><div class="fusion-note">左半：多張 8:5 持續流動。右半：每次 hover 都完整重新拼合；拼好後內容立即開始流動，鼠標移到右半即可停住閱讀，無需再點擊。</div></section></main><script src="/one/one-dore-cover-registry.js"></script><script src="/one/one-dore-assets-241.js"></script><script>
(function(){
 var layout=document.getElementById('layoutHalf'),stage=document.getElementById('assemblyHalf'),flow=document.getElementById('previewFlow'),R=window.ONE_DORE_COVER_REGISTRY||{},commons='https://commons.wikimedia.org/wiki/Special:Redirect/file/',cards=[].slice.call(document.querySelectorAll('.flow-card')),hoverMode=matchMedia('(hover:hover) and (pointer:fine)').matches,current=null,timer=0,run=0;
 function fileFor(id){if(R.files)return R.files[id]||R.files[String(id)];var x=R[id]||R[String(id)];return x&&(x.filename||x.file||x.name)||x}
 function url(id,w){var n=fileFor(id);return n?commons+encodeURIComponent(n)+'?width='+(w||1000):''}
 function visibleCards(){var lr=layout.getBoundingClientRect();return cards.filter(function(c){var r=c.getBoundingClientRect();return r.right>lr.left&&r.left<lr.right&&r.bottom>lr.top&&r.top<lr.bottom})}
 function clearPieces(){stage.querySelectorAll('.assembly-piece').forEach(function(p){p.remove()})}
 function grid(n,w,h){var cols=n<=4?2:(n<=9?3:4),rows=Math.ceil(n/cols),gap=4,cw=(w-gap*(cols-1))/cols,ch=(h-gap*(rows-1))/rows;return Array.from({length:n},function(_,i){return {x:(i%cols)*(cw+gap),y:Math.floor(i/cols)*(ch+gap),w:cw,h:ch}})}
 function esc(s){var d=document.createElement('div');d.textContent=s||'';return d.innerHTML}
 function readingSet(c,set){var idx=Math.max(0,set.indexOf(c)),ordered=[c].concat(set.slice(idx+1),set.slice(0,idx)).filter(function(x,i,a){return x&&a.indexOf(x)===i});if(ordered.length<3)ordered=ordered.concat(cards.filter(function(x){return ordered.indexOf(x)<0}).slice(0,3-ordered.length));return ordered.slice(0,Math.min(5,ordered.length))}
 function fillPreview(c,set){var rs=readingSet(c,set);flow.innerHTML=rs.map(function(x){return '<article class="preview-card"><small>'+esc(x.dataset.kind)+'</small><h3>'+esc(x.dataset.title)+'</h3><p>'+esc(x.dataset.preview)+'</p></article>'}).join('');flow.style.animation='none';void flow.offsetWidth;flow.style.animation='';}
 function activate(c){
   if(!c)return;current=c;run++;var my=run;stage.classList.remove('ready');cards.forEach(function(x){x.classList.toggle('selected',x===c)});
   var set=visibleCards();if(set.length<4)set=cards.slice(0,Math.min(6,cards.length));
   var sr=stage.getBoundingClientRect(),targets=grid(set.length,sr.width,sr.height),old=[].slice.call(stage.querySelectorAll('.assembly-piece'));
   old.forEach(function(p){p.animate([{opacity:1,transform:'scale(1)'},{opacity:0,transform:'scale(.82)'}],{duration:180,fill:'forwards',easing:'ease-in'}).onfinish=function(){p.remove()}});
   set.forEach(function(src,i){
      var r=src.getBoundingClientRect(),t=targets[i],p=document.createElement('i');p.className='assembly-piece';p.style.backgroundImage='url("'+url(src.dataset.dore,1000)+'")';p.style.left=t.x+'px';p.style.top=t.y+'px';p.style.width=t.w+'px';p.style.height=t.h+'px';stage.insertBefore(p,stage.firstChild);
      var dx=(r.left+r.width/2)-(sr.left+t.x+t.w/2),dy=(r.top+r.height/2)-(sr.top+t.y+t.h/2),sx=Math.max(.18,Math.min(1.5,r.width/t.w)),sy=Math.max(.18,Math.min(1.5,r.height/t.h));
      p.animate([{opacity:.35,transform:'translate('+dx+'px,'+dy+'px) scale('+sx+','+sy+')'},{opacity:1,transform:'translate(0,0) scale(1)'}],{duration:620+Math.min(i,8)*34,fill:'forwards',easing:'cubic-bezier(.22,.75,.18,1)'});
   });
   fillPreview(c,set);setTimeout(function(){if(my===run)stage.classList.add('ready')},760+Math.min(set.length,9)*34);
 }
 cards.forEach(function(c){var u=url(c.dataset.dore,900);if(u)c.style.backgroundImage='url("'+u+'")';if(hoverMode)c.addEventListener('mouseenter',function(){clearTimeout(timer);timer=setTimeout(function(){activate(c)},45)});c.addEventListener('click',function(e){if(!hoverMode){e.preventDefault();activate(c)}})});
 document.getElementById('clear').onclick=function(e){e.stopPropagation();run++;stage.classList.remove('ready');clearPieces();flow.innerHTML='';cards.forEach(function(x){x.classList.remove('selected')});current=null};
})();</script></body></html>'''